<?php
require_once __DIR__ . '/../includes/helpers.php'; require_login(); $pdo=db();
$from=$_GET['from']??date('Y-m-01'); $to=$_GET['to']??date('Y-m-d'); $dept=(int)($_GET['department_id']??0);
$where="DATE(a.attendance_datetime) BETWEEN ? AND ?"; $args=[$from,$to]; if($dept){$where.=" AND p.department_id=?";$args[]=$dept;}
$sql="SELECT a.attendance_datetime,a.attendance_method,p.school_id,CONCAT(p.first_name,' ',p.last_name) full_name,p.person_type,d.department_name FROM attendance_records a JOIN persons p ON p.person_id=a.person_id JOIN departments d ON d.department_id=p.department_id WHERE $where ORDER BY a.attendance_datetime DESC";
$q=$pdo->prepare($sql);$q->execute($args);$records=$q->fetchAll();
if(isset($_GET['export'])&&$_GET['export']==='csv'){
 header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="lamas-attendance-report.csv"');
 $out=fopen('php://output','w');fputcsv($out,['Date and time','School ID','Name','Type','Department','Method']);
 foreach($records as $r)fputcsv($out,[$r['attendance_datetime'],$r['school_id'],$r['full_name'],$r['person_type'],$r['department_name'],$r['attendance_method']]);fclose($out);exit;
}
$deptQ=$pdo->prepare("SELECT d.department_name,COUNT(*) visits FROM attendance_records a JOIN persons p ON p.person_id=a.person_id JOIN departments d ON d.department_id=p.department_id WHERE $where GROUP BY d.department_id ORDER BY visits DESC");$deptQ->execute($args);$byDept=$deptQ->fetchAll();
$student=$pdo->prepare("SELECT COUNT(*) FROM attendance_records a JOIN persons p ON p.person_id=a.person_id WHERE $where AND p.person_type='student'");$student->execute($args);$studentCount=(int)$student->fetchColumn();
$faculty=$pdo->prepare("SELECT COUNT(*) FROM attendance_records a JOIN persons p ON p.person_id=a.person_id WHERE $where AND p.person_type='faculty'");$faculty->execute($args);$facultyCount=(int)$faculty->fetchColumn();
$departments=$pdo->query("SELECT department_id,department_name FROM departments WHERE status='active' ORDER BY department_name")->fetchAll();
$pageTitle='Reports & Analytics';require __DIR__.'/../includes/header.php';
?>
<div class="d-flex flex-wrap justify-content-between align-items-center mb-4"><div><h1 class="h2 page-heading mb-1">Reports &amp; Analytics</h1><p class="text-secondary mb-0">Review attendance within a selected date range.</p></div><div class="d-flex gap-2"><button class="btn btn-outline-success" onclick="window.print()">Print / Save PDF</button><a class="btn btn-success" href="?<?=http_build_query(['from'=>$from,'to'=>$to,'department_id'=>$dept,'export'=>'csv'])?>">Export CSV</a></div></div>
<div class="panel mb-4"><form class="row g-2 align-items-end"><div class="col-md-3"><label class="form-label">From</label><input class="form-control" type="date" name="from" value="<?=e($from)?>" required></div><div class="col-md-3"><label class="form-label">To</label><input class="form-control" type="date" name="to" value="<?=e($to)?>" required></div><div class="col-md-4"><label class="form-label">Department</label><select class="form-select" name="department_id"><option value="0">All departments</option><?php foreach($departments as $d): ?><option value="<?=$d['department_id']?>" <?=$dept===(int)$d['department_id']?'selected':''?>><?=e($d['department_name'])?></option><?php endforeach; ?></select></div><div class="col-md-2"><button class="btn btn-outline-success w-100">Apply</button></div></form></div>
<div class="row g-3 mb-4"><div class="col-md-4"><div class="stat-card"><div class="stat-label">Total visits</div><div class="stat-value"><?=number_format(count($records))?></div></div></div><div class="col-md-4"><div class="stat-card"><div class="stat-label">Student visits</div><div class="stat-value"><?=number_format($studentCount)?></div></div></div><div class="col-md-4"><div class="stat-card"><div class="stat-label">Faculty visits</div><div class="stat-value"><?=number_format($facultyCount)?></div></div></div></div>
<div class="row g-3 mb-4"><div class="col-lg-8"><div class="panel"><h2 class="h5 fw-bold">Visits by department</h2><canvas id="deptChart" height="120"></canvas></div></div><div class="col-lg-4"><div class="panel"><h2 class="h5 fw-bold">Visitor type</h2><canvas id="typeChart"></canvas></div></div></div>
<div class="panel"><h2 class="h5 fw-bold mb-3">Attendance records (<?=count($records)?>)</h2><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Date &amp; time</th><th>Visitor</th><th>School ID</th><th>Type</th><th>Department</th><th>Method</th></tr></thead><tbody><?php foreach(array_slice($records,0,300) as $r): ?><tr><td><?=e($r['attendance_datetime'])?></td><td><?=e($r['full_name'])?></td><td><?=e($r['school_id'])?></td><td><?=e(ucfirst($r['person_type']))?></td><td><?=e($r['department_name'])?></td><td><?=e(strtoupper($r['attendance_method']))?></td></tr><?php endforeach; ?><?php if(!$records): ?><tr><td colspan="6" class="text-center text-secondary py-4">No attendance records in this date range.</td></tr><?php endif; ?></tbody></table></div><?php if(count($records)>300): ?><p class="small text-secondary mb-0">Showing first 300 rows. Export CSV to download all matching records.</p><?php endif; ?></div>
<script src="https://cdn.jsdelivr.net/npm/chart.js"></script><script>
new Chart(document.getElementById('deptChart'),{type:'bar',data:{labels:<?=json_encode(array_column($byDept,'department_name'),JSON_HEX_TAG|JSON_HEX_APOS)?>,datasets:[{label:'Visits',data:<?=json_encode(array_map('intval',array_column($byDept,'visits')))?>,backgroundColor:'#26845d',borderRadius:6}]},options:{responsive:true,plugins:{legend:{display:false}},scales:{y:{beginAtZero:true,ticks:{precision:0}}}}});
new Chart(document.getElementById('typeChart'),{type:'doughnut',data:{labels:['Students','Faculty'],datasets:[{data:[<?=$studentCount?>,<?=$facultyCount?>],backgroundColor:['#26845d','#b8d9c7']}]},options:{plugins:{legend:{position:'bottom'}}}});
</script>
<?php require __DIR__.'/../includes/footer.php'; ?>